; ============================================================================
; Quiz Battle - multi-subject question banks (grades 1-5)
; ----------------------------------------------------------------------------
; GENERATED by tools_gen_quiz.py -- edit that script and re-run it, then `make`.
; Each grade's data lives in its own ROM bank; the engine copies a chosen
; question into RAM before showing it (see QuizLoadQuestion).
; ============================================================================

; One question entry (18 bytes), emitted as raw directives:
;   dw QUESTION | db CORRECT(0) | db NUM_ANSWERS(2-6) | dw ANS0..ANS5 | dw HINT
; Absent answer slots reuse the last real answer's label so all 6 pointers
; are valid (the engine only shows NUM_ANSWERS of them).

QuizGradeTable::
	dw Grade1Questions
	db 100
	db BANK(Grade1Questions)
	dw Grade2Questions
	db 100
	db BANK(Grade2Questions)
	dw Grade3Questions
	db 100
	db BANK(Grade3Questions)
	dw Grade4Questions
	db 100
	db BANK(Grade4Questions)
	dw Grade5Questions
	db 100
	db BANK(Grade5Questions)

; ---- result messages (shown via PrintText) ----
; NOTE: a literal-text segment must end with '@' BEFORE a text_ram command,
; otherwise the text engine runs past it and never prints the RAM string.
QuizCorrectText::
	text "CORRECT ANSWER!"
	line "Streak @"
	text_ram wStringBuffer
	text "<PROMPT>"

; shown when the streak crosses a power milestone (x1.5 at 4, x2.0 at 8)
QuizPowerUpText::
	text "CORRECT! POWER UP"
	line "Streak @"
	text_ram wStringBuffer
	text "<PROMPT>"

QuizMaxPowerText::
	text "CORRECT MAX POWER"
	line "Streak @"
	text_ram wStringBuffer
	text "<PROMPT>"

; first wrong try: say it's wrong, then teach via the hint and re-ask
QuizTryAgainText::
	text "WRONG ANSWER!"
	line "@"
	text_ram wStringBuffer
	text "<PROMPT>"

; final wrong: say it's wrong, then reveal the answer so it still teaches
QuizMissText::
	text "WRONG ANSWER!"
	line "It is @"
	text_ram wStringBuffer
	text "<PROMPT>"

